procedure Store_Compilation_Switch (Switch : String) is
begin
   if Switch_Storing_Enabled then
      Compilation_Switches.Increment_Last;
      Compilation_Switches.Table (Compilation_Switches.Last) :=
        new String'(Switch);

      --  Fix up --RTS flag which has been transformed by the gcc driver
      --  into -fRTS

      if Switch'Last >= Switch'First + 4
        and then Switch (Switch'First .. Switch'First + 4) = "-fRTS"
      then
         Compilation_Switches.Table
           (Compilation_Switches.Last) (Switch'First + 1) := '-';
      end if;
   end if;
end Store_Compilation_Switch;

if T = Source then
   declare
      Name : String renames Name_Buffer (1 .. Name_Len);
      Inc  : String renames Include_Dir_Default_Prefix.all;

      Part_Of_Runtimes : constant Boolean :=
        Inc /= ""
          and then Inc'Length < Name_Len
          and then Name_Buffer (1 .. Inc'Length) = Inc;

   begin
      if Debug.Debug_Flag_Dot_N then
         Write_Line (Name);
      end if;

      if not Part_Of_Runtimes then
         File_Name_Chars.Append_All (File_Name_Chars.Table_Type (Name));
         File_Name_Chars.Append (ASCII.LF);
      end if;
   end;
end if;

function Load_Definition_File
  (N : File_Name_Type) return Source_File_Index
is
begin
   return Load_File (N, Osint.Definition);
end Load_Definition_File;

---------------
-- Load_File --
---------------

function Load_File
  (N : File_Name_Type;
   T : Osint.File_Type) return Source_File_Index
is
   FD  : File_Descriptor;
   Hi  : Source_Ptr;
   Lo  : Source_Ptr;
   Src : Source_Buffer_Ptr;
   X   : Source_File_Index;

   Preprocessing_Needed : Boolean := False;

begin
   --  If already there, don't need to reload file. An exception occurs
   --  in multiple unit per file mode. It would be nice in this case to
   --  share the same source file for each unit, but this leads to many
   --  difficulties with assumptions (e.g. in the body of lib), that a
   --  unit can be found by locating its source file index. Since we do
   --  not expect much use of this mode, it's no big deal to waste a bit
   --  of space and time by reading and storing the source multiple times.

   if Multiple_Unit_Index = 0 then
      for J in 1 .. Source_File.Last loop
         if Source_File.Table (J).File_Name = N then
            return J;
         end if;
      end loop;
   end if;

   --  Here we must build a new entry in the file table

   --  But first, we must check if a source needs to be preprocessed,
   --  because we may have to load and parse a definition file, and we want
   --  to do that before we load the source, so that the buffer of the
   --  source will be the last created, and we will be able to replace it
   --  and modify Hi without stepping on another buffer.

   if T = Osint.Source and then not Is_Internal_File_Name (N) then
      Prepare_To_Preprocess
        (Source => N, Preprocessing_Needed => Preprocessing_Needed);
   end if;

   Source_File.Increment_Last;

Osint.Read_Source_File (N, Lo, Hi, Src, FD, T);

if Null_Source_Buffer_Ptr (Src) then
   Source_File.Decrement_Last;

   if FD = Osint.Null_FD then
      return No_Source_File;
   else
      return No_Access_To_Source_File;
   end if;

      end if;
   end loop;
end if;

--  If we are proceeding with load, then make load stack entry,
--  and indicate the kind of with_clause responsible for the load.

Load_Stack.Increment_Last;
Load_Stack.Table (Load_Stack.Last) := (Unum, With_Node);

--  Case of entry already in table

if Unum <= Units.Last then

   --  Here is where we check for a circular dependency, which is
   --  an attempt to load a unit which is currently in the process
   --  of being loaded. We do *not* care about a circular chain that
   --  leads back to a body, because this kind of circular dependence
   --  legitimately occurs (e.g. two package bodies that contain
   --  inlined subprograms referenced by each other).

   --  Ada 2005 (AI-50217): We also ignore limited_with clauses, because
   --  their purpose is precisely to create legal circular structures.

   if Loading (Unum)
     and then (Is_Spec_Name (Units.Table (Unum).Unit_Name)
                 or else Acts_As_Spec (Units.Table (Unum).Cunit))
     and then (Nkind (Error_Node) /= N_With_Clause
