           ("circular unit dependency", Load_Msg_Sloc, Error_Node);
         Write_Dependency_Chain;
      else
         Load_Stack.Decrement_Last;
      end if;

      Unum := No_Unit;
      goto Done;
   end if;

   if Debug_Flag_L then
      Write_Str ("  unit already in file table, Unit_Number = ");
      Write_Int (Int (Unum));
      Write_Eol;
   end if;

   Load_Stack.Decrement_Last;
   goto Done;

