-- Lowest_Common_Ancestor --
----------------------------

function Lowest_Common_Ancestor (N1, N2 : Node_Id) return Union_Id is
   function Path_From_Root (N : Node_Id) return Lists.Doubly_Linked_List;

   --------------------
   -- Path_From_Root --
   --------------------

   function Path_From_Root (N : Node_Id) return Lists.Doubly_Linked_List is
      L : constant Lists.Doubly_Linked_List := Lists.Create;

      X : Union_Id := Union_Id (N);
   begin
      while X /= Union_Id (Empty) loop
         Lists.Prepend (L, X);
         X := Parent_Or_List_Containing (X);
      end loop;

      return L;
   end Path_From_Root;

   L1 : Lists.Doubly_Linked_List := Path_From_Root (N1);
   L2 : Lists.Doubly_Linked_List := Path_From_Root (N2);

   X1, X2 : Union_Id;

   Common_Ancestor : Union_Id := Union_Id (Empty);
begin
   while not Lists.Is_Empty (L1) and then not Lists.Is_Empty (L2) loop
      X1 := Lists.First (L1);
      Lists.Delete_First (L1);

      X2 := Lists.First (L2);
      Lists.Delete_First (L2);

      exit when X1 /= X2;

      Common_Ancestor := X1;
   end loop;

   Lists.Destroy (L1);
   Lists.Destroy (L2);

   return Common_Ancestor;

elsif Ekind (Label_Ent) /= E_Label then
   Error_Msg_N ("target of goto statement must be a label", Label);
   return;

--  Check that the target of the goto is reachable according to Ada
--  scoping rules. Note: the special gotos we generate for optimizing
--  local handling of exceptions would violate these rules, but we mark
--  such gotos as analyzed when built, so this code is never entered.

elsif not Reachable (Label_Ent) then
   Error_Msg_N ("target of goto statement is not reachable", Label);
   return;
end if;

Finally_Legality_Check : declare
