function Len_Arg (Arg : Pos) return Nat is
begin
   for J in 1 .. Nat'Last loop
      if save_argv (Arg).all (Natural (J)) = ASCII.NUL then
         return J - 1;
      end if;
   end loop;

   raise Program_Error;
end Len_Arg;

