procedure Scan_Compiler_Arguments is
   Next_Arg : Positive;
   --  Next argument to be scanned

   Arg_Count : constant Natural := Natural (save_argc - 1);
   Args      : Argument_List (1 .. Arg_Count);

   Output_File_Name_Seen : Boolean := False;

for Arg in Pos range 1 .. save_argc - 1 loop
   declare
      Argv_Ptr : constant Big_String_Ptr := save_argv (Arg);
      Argv_Len : constant Nat            := Len_Arg (Arg);
      Argv     : constant String         :=
                   Argv_Ptr (1 .. Natural (Argv_Len));
   begin
      Args (Positive (Arg)) := new String'(Argv);
   end;
end loop;

--  Loop through command line arguments, storing them for later access

Next_Arg := 1;
while Next_Arg <= Args'Last loop

--  -gnatec (configuration pragmas)

when 'c' =>
   Store_Switch := False;
   Ptr := Ptr + 1;

   --  There may be an equal sign between -gnatec and
   --  the path name of the config file.

   if Ptr <= Max and then Switch_Chars (Ptr) = '=' then
      Ptr := Ptr + 1;
   end if;

   if Ptr > Max then
      Bad_Switch ("-gnatec");
   end if;

   declare
      Config_File_Name : constant String_Access :=
                           new String'
                                (Switch_Chars (Ptr .. Max));

   begin
      if Config_File_Names = null then
         Config_File_Names :=
           new String_List'(1 => Config_File_Name);

      else
         declare
            New_Names : constant String_List_Access :=
                          new String_List
                            (1 ..
                             Config_File_Names'Length + 1);

         begin
            for Index in Config_File_Names'Range loop
               New_Names (Index) :=
                 Config_File_Names (Index);
               Config_File_Names (Index) := null;
            end loop;

            New_Names (New_Names'Last) := Config_File_Name;
            Free (Config_File_Names);
            Config_File_Names := New_Names;
         end;
      end if;
   end;

   return;

--  -gnatem (mapping file)

when 'm' =>
   Store_Switch := False;
   Ptr := Ptr + 1;

   --  There may be an equal sign between -gnatem and
   --  the path name of the mapping file.

   if Ptr <= Max and then Switch_Chars (Ptr) = '=' then
      Ptr := Ptr + 1;
   end if;

   if Ptr > Max then
      Bad_Switch ("-gnatem");
   end if;

   Mapping_File_Name :=
     new String'(Switch_Chars (Ptr .. Max));
   return;

   --  Anything else is an error (illegal switch character)

   when others =>
      Bad_Switch ("-gnat" & Switch_Chars (Ptr .. Max));
   end case;

   if Store_Switch then
      Store_Compilation_Switch
        ("-gnat" & Switch_Chars (First_Char .. Ptr - 1));
   end if;

   First_Switch := False;
end loop;

