-- Chosen_Interval --
---------------------

function Chosen_Interval (Choice : Node_Id) return Discrete_Interval is
begin
   case Nkind (Choice) is
      when N_Range =>
         return (Low  => Expr_Value (Low_Bound (Choice)),
                 High => Expr_Value (High_Bound (Choice)));

      when N_Subtype_Indication =>
         declare
            Range_Exp : constant Node_Id :=
              Range_Expression (Constraint (Choice));
         begin
            return (Low  => Expr_Value (Low_Bound (Range_Exp)),
                    High => Expr_Value (High_Bound (Range_Exp)));

procedure Preanalyze_Without_Errors (N : Node_Id);
--  Preanalyze N without reporting errors

package Interval_Lists is
   type Discrete_Interval is
      record
         Low, High : Uint;
      end record;

   type Discrete_Interval_List is
     array (Pos range <>) of Discrete_Interval;
   --  A sorted (in ascending order) list of non-empty pairwise-disjoint
   --  intervals, always with a gap of at least one value between
   --  successive intervals (i.e., mergeable intervals are merged).
   --  Low bound is one; high bound is nonnegative.

--  Check for duplicates for discrete case

if Is_Discrete_Type (T) then
   declare
      type Ent is record
         Alt : Node_Id;
         Val : Uint;
      end record;

      Alts  : array (0 .. List_Length (Alternatives (N))) of Ent;
      Nalts : Nat;

   begin
      --  Loop checking duplicates. This is quadratic, but giant sets
      --  are unlikely in this context so it's a reasonable choice.

      Nalts := 0;
      Alt := First (Alternatives (N));
      while Present (Alt) loop
         if Is_OK_Static_Expression (Alt)
           and then Nkind (Alt) in N_Integer_Literal
                                 | N_Character_Literal
                                 | N_Has_Entity
         then
            Nalts := Nalts + 1;
            Alts (Nalts) := (Alt, Expr_Value (Alt));

            for J in 1 .. Nalts - 1 loop
               if Alts (J).Val = Alts (Nalts).Val then
                  Error_Msg_Sloc := Sloc (Alts (J).Alt);
                  Error_Msg_N ("duplicate of value given#??", Alt);
               end if;
            end loop;
         end if;

         Next (Alt);
      end loop;
   end;

package body Generic_Check_Choices is

